// План specs/dashboard.md 1.3 (кейс DB-03). Планшет 768×1024 (Chrome), admin, компания «test». Только просмотр (@prod-safe).
import { test } from '@playwright/test';
import { ADMIN_STATE } from '../addresses/address-helpers';
import { Lang, expectClearViewBlockRemoved, expectSalesJobsRightAfterGreeting, openDashboard } from './dashboard-helpers';

test.use({ storageState: ADMIN_STATE, viewport: { width: 768, height: 1024 } });

test.describe('Дашборд на планшете: блока «A clear view of your day» нет (#b6cecf04)', () => {
  const cases: { lang: Lang; label: string }[] = [
    { lang: 'en', label: 'EN' },
    { lang: 'he', label: 'HE' },
  ];

  for (const { lang, label } of cases) {
    test(`Tablet 768 dashboard ${label}: no "A clear view of your day" block, Sales & Jobs right after greeting #b6cecf04 @android @prod-safe`, async ({ page }) => {
      await openDashboard(page, lang);
      await expectClearViewBlockRemoved(page);
      await expectSalesJobsRightAfterGreeting(page, lang);
    });
  }
});
